    # The color-4 object is the exemplar pattern.
    exemplar=set().union(*_components(grid,4))
    r0=min(r for r,c in exemplar); c0=min(c for r,c in exemplar)
    shape={(r-r0,c-c0) for r,c in exemplar}
    sh,sw=max(r for r,c in shape)+1,max(c for r,c in shape)+1
    for color in sorted({v for row in grid for v in row}-{1,4}):
